def deux_sommes(nombres, cible):
    vus = {}
    for i, n in enumerate(nombres):
        if cible - n in vus:
            return [vus[cible - n], i]
        vus[n] = i
    return None

print(deux_sommes([1200, 300, 650, 900], 1550))
print(deux_sommes([1, 2], 10))

