exercises.solution:
def anagrammes(mots):
    groupes = {}
    for mot in mots:
        groupes.setdefault("".join(sorted(mot)), []).append(mot)
    return list(groupes.values())

from collections import Counter

def premier_unique(ventes):
    compte = Counter(ventes)
    for article in ventes:
        if compte[article] == 1:
            return article
    return None
